"""One read-only MCP tool for flight status. Install: pip install "mcp[cli]"."""
from typing import Annotated

from pydantic import Field
from mcp.server import MCPServer
from mcp.types import ToolAnnotations

mcp = MCPServer("Mokaair Flight Desk")

# Demo data only: a fixed table so the example has no external dependency.
_STATUS = {
  "CI100": "on_time",
  "CI102": "delayed_30m",
  "BR225": "boarding",
}


@mcp.tool(
  title="Look up one flight's status",
  annotations=ToolAnnotations(read_only_hint=True, open_world_hint=False),
)
def flight_status(
  flight_no: Annotated[str, Field(description="Flight number, such as CI100.")],
) -> str:
  """Return one flight's status from the demo schedule."""
  return _STATUS.get(flight_no.upper(), "unknown")


if __name__ == "__main__":
  mcp.run()
